import java.util.Scanner;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();

        long[] s = new long[n + 1];
        long[] t = new long[n + 1];

        Arrays.fill(s, 1);
        System.arraycopy(s, 0, t, 0, s.length);

        for (int m = 1; m <= n; m++) {
            long sum = 0;
            for (int k = 0; k < m; k++) {
                sum += s[m - 1 - k] * s[k];
            }
            s[m] = sum;
        }

        for (int _ = 0; _ < h; _++) {
            long[] t_new = new long[n + 1];
            for (int m = 0; m <= n; m++) {
                long total = 0;
                for (int k = 0; k < m; k++) {
                    total += (s[k] - t[k]) * t[m - 1 - k] + s[m - 1 - k] * t[k];
                }
                t_new[m] = total;
            }
            t = t_new;
        }

        System.out.println(t[n]);
        sc.close();
    }
}
